CREATE TABLE IF NOT EXISTS secure_store_secrets (alias TEXT PRIMARY KEY, kind TEXT NOT NULL, label TEXT, origin_server_id TEXT, origin_server_name TEXT, origin_server_kind TEXT, origin_source TEXT, origin_field_group TEXT, origin_field_key TEXT, origin_field_index INTEGER, origin_field_path TEXT, provider_id TEXT NOT NULL, provider_kind TEXT NOT NULL, version INTEGER NOT NULL, key_nonce TEXT NOT NULL, encrypted_key TEXT NOT NULL, nonce TEXT NOT NULL, encrypted_value TEXT NOT NULL, key_wrap_alg TEXT NOT NULL DEFAULT 'AES-256-GCM', encryption_alg TEXT NOT NULL DEFAULT 'AES-256-GCM', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS secure_store_usages (id TEXT PRIMARY KEY, alias TEXT NOT NULL, server_id TEXT NOT NULL, location_kind TEXT NOT NULL, location_name TEXT, location_index INTEGER, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (alias) REFERENCES secure_store_secrets (alias) ON DELETE CASCADE, UNIQUE(alias, server_id, location_kind, location_name, location_index));
CREATE TABLE IF NOT EXISTS secure_store_password_config (id INTEGER PRIMARY KEY CHECK (id = 1), password_hash TEXT NOT NULL, hash_salt TEXT NOT NULL, hash_iterations INTEGER NOT NULL DEFAULT 600000, protection_scope TEXT NOT NULL DEFAULT '["startup"]', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS secure_store_provider_config (id INTEGER PRIMARY KEY CHECK (id = 1), provider_mode TEXT NOT NULL DEFAULT 'operating_system', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
